import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() {
            if (ptr >= len) {
                try {
                    len = in.read(buffer);
                    ptr = 0;
                } catch (IOException e) {
                    return -1;
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= ' ' && c != -1) {
                c = read();
            }
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        int[] x = new int[n + 1];
        int[] y = new int[n + 1];
        x[0] = 0;
        y[0] = 0;

        for (int i = 1; i <= n; i++) {
            x[i] = fs.nextInt();
            y[i] = fs.nextInt();
        }

        int totalEdges = n * (n - 1) / 2 + n;
        int[] u = new int[totalEdges];
        int[] v = new int[totalEdges];
        int[] dist = new int[totalEdges];

        int edgeCount = 0;
        for (int i = 1; i <= n; i++) {
            u[edgeCount] = 0;
            v[edgeCount] = i;
            long dx = x[i];
            long dy = y[i];
            dist[edgeCount] = (int) (dx * dx + dy * dy);
            edgeCount++;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                u[edgeCount] = i;
                v[edgeCount] = j;
                long dx = x[i] - x[j];
                long dy = y[i] - y[j];
                dist[edgeCount] = (int) (dx * dx + dy * dy);
                edgeCount++;
            }
        }

        // Radix sort nas arestas por dist
        int[] p = new int[totalEdges];
        for (int i = 0; i < totalEdges; i++) p[i] = i;

        int[] pTemp = new int[totalEdges];
        final int BITS = 10;
        final int BUCKETS = 1 << BITS;
        final int MASK = BUCKETS - 1;
        int[] count = new int[BUCKETS];

        for (int shift = 0; shift < 30; shift += BITS) {
            for (int i = 0; i < BUCKETS; i++) count[i] = 0;
            for (int i = 0; i < totalEdges; i++) {
                int val = (dist[p[i]] >> shift) & MASK;
                count[val]++;
            }
            int sum = 0;
            for (int i = 0; i < BUCKETS; i++) {
                int c = count[i];
                count[i] = sum;
                sum += c;
            }
            for (int i = 0; i < totalEdges; i++) {
                int val = (dist[p[i]] >> shift) & MASK;
                pTemp[count[val]++] = p[i];
            }
            int[] swap = p;
            p = pTemp;
            pTemp = swap;
        }

        int[] dp = new int[n + 1];
        int[] tempDp = new int[n + 1];
        int[] touched = new int[n + 1];
        int touchedCount = 0;

        int ans = 0;

        int i = 0;
        while (i < totalEdges) {
            int j = i;
            int curDist = dist[p[i]];
            while (j < totalEdges && dist[p[j]] == curDist) {
                j++;
            }

            touchedCount = 0;
            for (int k = i; k < j; k++) {
                int edgeIdx = p[k];
                int uu = u[edgeIdx];
                int vv = v[edgeIdx];

                if (uu == 0) {
                    if (dp[vv] + 1 > ans) {
                        ans = dp[vv] + 1;
                    }
                } else {
                    int candU = dp[vv] + 1;
                    int candV = dp[uu] + 1;

                    if (tempDp[uu] == 0) {
                        tempDp[uu] = dp[uu];
                        touched[touchedCount++] = uu;
                    }
                    if (candU > tempDp[uu]) {
                        tempDp[uu] = candU;
                    }

                    if (tempDp[vv] == 0) {
                        tempDp[vv] = dp[vv];
                        touched[touchedCount++] = vv;
                    }
                    if (candV > tempDp[vv]) {
                        tempDp[vv] = candV;
                    }
                }
            }

            for (int k = 0; k < touchedCount; k++) {
                int node = touched[k];
                dp[node] = tempDp[node];
                tempDp[node] = 0;
            }

            i = j;
        }

        System.out.println(ans);
    }
}
